package com.citacloud.app.models; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="consultas_medicas") public class ConsultaMedica {@Id @GeneratedValue private UUID id;@Column(name="empresa_id")private UUID empresaId;@Column(name="cita_id")private UUID citaId;@Column(name="paciente_id")private UUID pacienteId;@Column(name="medico_id")private UUID medicoId;private String motivo;@Column(name="historia_actual")private String historiaActual;@Column(name="examen_observaciones")private String examenObservaciones;private String estado="BORRADOR";public UUID getId(){return id;}public UUID getEmpresaId(){return empresaId;}public void setEmpresaId(UUID v){empresaId=v;}public UUID getCitaId(){return citaId;}public void setCitaId(UUID v){citaId=v;}public UUID getPacienteId(){return pacienteId;}public void setPacienteId(UUID v){pacienteId=v;}public UUID getMedicoId(){return medicoId;}public void setMedicoId(UUID v){medicoId=v;}public String getMotivo(){return motivo;}public void setMotivo(String v){motivo=v;}public String getHistoriaActual(){return historiaActual;}public void setHistoriaActual(String v){historiaActual=v;}public String getExamenObservaciones(){return examenObservaciones;}public void setExamenObservaciones(String v){examenObservaciones=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;}}
